function inputRows(records){const shown=records.slice(0,ui.inputShown),hidden=records.length-shown.length,driver=d=>`<button type="button" data-q-select="${esc(d.id)}"><small>${esc(driverCode(project,d))} · ${esc(concern(d).name)}</small><b>${esc(d.title)}</b></button>`;return `<div class="q-source-list">${shown.map(a=>{const ds=project.quality.drivers.filter(d=>d.requirementIds.includes(a.id));return `<details data-work-source="${esc(a.id)}" ${ui.inputFocusId===a.id?'open':''}><summary><span><small>${a.externalId?esc(a.externalId)+' · ':''}${esc(a.id)} · ${a.owner?esc(a.owner):'Owner missing'}</small><strong>${esc(a.title)}</strong></span><span class="q-source-result"><b>${ds.length} linked ${ds.length===1?'driver':'drivers'}</b><small>${a.confirmed?'Source confirmed':'Source unconfirmed'}</small></span></summary><div class="q-source-reading"><section><span class="eyebrow">Required behaviour</span><p>${esc(a.description)}</p><div class="r-acceptance"><span>Verify with</span><p>${esc(a.acceptance||'Acceptance not recorded in Chapter 1.')}</p></div><a class="r-btn" href="${esc(projectURL('/?chapter=1&tab=work&section=requirement&artefact='+encodeURIComponent(a.id)))}">Open source requirement ${icon('arrow')}</a></section><section><span class="eyebrow">Architectural consequences</span><div class="q-linked-pills">${ds.slice(0,4).map(driver).join('')||'<p>No architectural driver is linked to this source yet.</p>'}</div>${ds.length>4?`<details><summary>Show ${ds.length-4} more linked drivers</summary><div class="q-linked-pills">${ds.slice(4).map(driver).join('')}</div></details>`:''}<button type="button" class="r-btn primary" data-q-from-requirement="${esc(a.id)}">Add a linked driver</button></section></div></details>`}).join('')||`<div class="r-empty"><h3>${ui.inputQuery?'No matching requirements.':'No requirements yet.'}</h3><p>${ui.inputQuery?'Try another ID or title.':'Add requirements in Chapter 1 before recording their drivers.'}</p>${ui.inputQuery?'':`<a class="r-btn" href="${esc(projectURL('/?chapter=1&tab=work'))}">Open Chapter 1</a>`}</div>`}</div>${hidden?`<p class="l-pager"><button type="button" class="btn" data-q-action="show-inputs">Show 50 more</button><small>${shown.length} of ${records.length} matching requirements shown · ${Math.min(50,hidden)} more.</small></p>`:''}`}
function intake(){const records=reqs().filter(inScope),quality=project.quality.drivers.filter(d=>isMeasured(d)&&inScope(d));return `<div class="q-intake-summary"><span><b>${records.filter(a=>a.confirmed).length}/${records.length}</b>Requirements confirmed</span><span><b>${project.quality.drivers.filter(inScope).length}</b>Architectural drivers</span><span><b>${quality.length}</b>Measurable quality scenarios</span><span><b>${quality.filter(d=>!d.targetConfirmed).length}</b>Unconfirmed quality targets</span></div><div class="r-reference-note">Recording an input review does not confirm the requirements. Example scenarios and numerical targets still need project evidence.</div><label class="l-field"><span>Find an inherited requirement</span><input id="q-input-search" type="search" value="${esc(ui.inputQuery)}" placeholder="Search source ID, title, or owner…"></label><div id="q-input-results">${inputRows(matchingInputs())}</div>`}
function filtered(){return orderedDrivers(project).filter(d=>inScope(d)&&(ui.kind==='all'||driverKind(d)===ui.kind)&&(ui.category==='all'||isMeasured(d)&&d.category===ui.category)&&(!ui.query||[d.id,driverCode(project,d),d.scenarioId,d.title,d.owner,d.metric,d.description,d.impact].join(' ').toLowerCase().includes(ui.query.toLowerCase())))}
function register(){return `<div class="q-register-tools"><label><span class="r-sr-only">Find a driver</span><input id="q-search" type="search" placeholder="Find a code, driver, or owner…" value="${esc(ui.query)}"></label><label><span class="r-sr-only">Filter the kind of driver</span><select id="q-kind"><option value="all">All kinds</option>${DRIVER_KINDS.map(k=>`<option value="${k.id}" ${ui.kind===k.id?'selected':''}>${esc(k.plural)}</option>`).join('')}</select></label><label><span class="r-sr-only">Filter quality concern (quality scenarios only)</span><select id="q-category" ${ui.kind!=='all'&&ui.kind!=='quality'?'disabled':''}><option value="all">All quality concerns</option>${QUALITY_TYPES.map(t=>`<option value="${esc(t.id)}" ${ui.category===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label></div><p class="r-note">Browse all eight kinds of architectural driver. Quality scenarios have measurable targets; other drivers describe their impact. Order uses named priority, then your order within it.</p><div id="q-driver-list">${driverList()}</div>`}
function driverList(){const all=orderedDrivers(project);return filtered().map(d=>`<article class="q-driver-row ${ui.selected===d.id?'selected':''}" data-work-record-row="${esc(d.id)}"><div><button class="q-driver-main" data-q-select="${esc(d.id)}" data-q-insight="driver:${esc(d.id)}"><span class="q-driver-meta"><i style="background:${concern(d).color}"></i>${esc(driverCode(project,d))} · ${esc(concern(d).name)}</span><h3>${esc(d.title)}</h3>${driverKind(d)==='quality'?`<p>${esc(d.metric||'Metric not defined')} <strong>${esc(targetText(d))}</strong></p>`:`<p>${esc(d.impact||d.description||'Impact on the architecture not stated')}</p>`}<small>${d.requirementIds.length} requirements${d.requirementGroupIds?.length?' · '+d.requirementGroupIds.length+' groups':''} · ${d.responsibilityIds.length} responsibilities${designAsksLine(d)}</small></button>${workTraceHTML([{label:'Direct source requirements',records:d.requirementIds.map(id=>{const r=project.artefacts.find(a=>a.id===id);return r?{...r,chapter:1,section:'requirement'}:null;}),empty:'No direct requirement link recorded',more:'/?chapter=2&tab=model&driver='+encodeURIComponent(d.id)},{label:'Affected responsibilities',records:d.responsibilityIds.map(id=>{const r=project.logical?.responsibilities.find(a=>a.id===id);return r?{...r,chapter:4,section:'responsibilities'}:null;}),empty:'No responsibility link recorded',more:'/?chapter=2&tab=model&driver='+encodeURIComponent(d.id)}])}</div><div class="q-driver-row-actions"><span class="q-priority">${esc(driverPriority(d)||'Not stated')} · ${all.indexOf(d)+1}</span>${driverKind(d)==='quality'?targetBadge(d):''}<button class="r-btn" data-q-edit="${esc(d.id)}" aria-label="Edit ${esc(d.id)}">${icon('edit')}Edit</button></div></article>`).join('')||'<div class="r-empty"><h3>No drivers in this view.</h3><p>Choose another kind or concern, or add a driver.</p></div>'}
function comparison(){
 const all=orderedDrivers(project),ordered=all.filter(inScope);
 // The comparison is a view selection, never a change to the saved drivers or their global ranks.
 const pair=[0,1].map(i=>ordered.some(d=>d.id===ui.compare[i])?ui.compare[i]:null);
 if(pair[0]===pair[1])pair[1]=null;
 for(let i=0;i<2;i++)if(!pair[i])pair[i]=ordered.find(d=>!pair.includes(d.id))?.id||null;
 ui.compare=pair;
 const a=driver(pair[0]),b=driver(pair[1]);
 const viewRows={
  purpose:[['Kind',d=>kindLabel(d)],['Description',d=>d.description],['Architectural impact',d=>d.impact],['Priority and reason',d=>(driverPriority(d)||'Not stated')+' — '+(d.rationale||'Reason not recorded')]],
  scenario:[['Stimulus',d=>isMeasured(d)?d.stimulus:'Measured scenarios apply only to quality drivers'],['Conditions',d=>isMeasured(d)?d.conditions:'Measured scenarios apply only to quality drivers'],['Response',d=>isMeasured(d)?d.response:'Measured scenarios apply only to quality drivers']],
  measurement:[['Target',d=>isMeasured(d)?d.metric+' · '+targetText(d):'Only quality scenarios have measured targets'],['Verification',d=>isMeasured(d)?d.measurement+' · '+d.window:'Only quality scenarios have a verification measure']],
  rationale:[['Priority',d=>(driverPriority(d)||'Not stated')+' — '+d.rationale],['Requirements',d=>d.requirementIds.join(', ')],['Responsibilities',d=>d.responsibilityIds.map(id=>projectResponsibilities(project).find(r=>r.id===id)?.title).join(', ')],['Candidate tactic',d=>isMeasured(d)?d.tactic:'Tactics are recorded on quality scenarios']]
 };
 const body=ui.section==='priorities'?`<p class="r-intro">High protects a non-negotiable outcome. Medium materially affects the service. Low improves the experience. A driver with no stated priority weighs nothing when a decision is read. Each priority needs a reason.</p>${shellLens()?'<p class="r-note">Showing drivers in this module scope. Positions and moves use the project’s full priority order.</p>':''}<div class="q-priority-list">${ordered.map(d=>{const group=all.filter(x=>driverPriority(x)===driverPriority(d)),i=group.indexOf(d);return `<div><span class="q-order">${all.indexOf(d)+1}</span><button data-q-select="${esc(d.id)}"><small>${esc(driverCode(project,d))} · ${esc(driverPriority(d)||'Not stated')}</small><b>${esc(d.title)}</b><span>${esc(d.rationale||'Priority reason missing')}</span></button><div><button class="r-btn" data-q-move="${esc(d.id)}" data-direction="up" aria-label="Move ${esc(driverCode(project,d))} up within ${esc(driverPriority(d)||'not stated')}" ${i===0?'disabled':''}>↑</button><button class="r-btn" data-q-move="${esc(d.id)}" data-direction="down" aria-label="Move ${esc(driverCode(project,d))} down within ${esc(driverPriority(d)||'not stated')}" ${i===group.length-1?'disabled':''}>↓</button><button class="r-btn" data-q-edit="${esc(d.id)}" aria-label="Edit priority for ${esc(d.id)}">Edit</button></div></div>`}).join('')||'<p class="r-note">No drivers in this scope. Add a driver or choose another module scope.</p>'}</div>`
 :ui.section==='conflicts'?`<h3>Recorded conflicts</h3>${conflictList()}<details class="f-disclosure"><summary>Explore potential trade-offs · ${potentialTradeoffs(project,null).filter(pairInScope).length}</summary><p class="r-note">These are prompts for review. A conflict is recorded only when you choose to record one.</p><div class="f-tradeoffs">${tradeoffList(null,true)}</div></details>`
 :`<div class="l-form-grid">${[0,1].map(i=>`<label class="l-field"><span>${i?'Second':'First'} driver</span><select data-q-compare="${i}" ${ordered.length<2?'disabled':''}>${!ui.compare[i]?'<option value="">'+(ordered.length?'Another driver is needed':'No drivers in this scope')+'</option>':''}${ordered.map(d=>`<option value="${esc(d.id)}" ${ui.compare[i]===d.id?'selected':''}>${esc(driverCode(project,d))} · ${esc(d.title)}</option>`).join('')}</select></label>`).join('')}</div>${a&&b?`<label class="f-criterion-picker"><span>Compare aspect</span><select id="q-compare-view">${[['purpose','Purpose & impact'],['scenario','Quality scenario'],['measurement','Quality measurement'],['rationale','Rationale & traceability']].map(([id,label])=>`<option value="${esc(id)}" ${ui.compareView===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="q-comparison-scroll"><table class="q-comparison"><thead><tr><th>Compare</th><th>${esc(driverCode(project,a))} · ${esc(kindLabel(a))}</th><th>${esc(driverCode(project,b))} · ${esc(kindLabel(b))}</th></tr></thead><tbody>${(viewRows[ui.compareView]||viewRows.purpose).map(([name,value])=>`<tr><th>${name}</th><td>${esc(value(a)||'Not recorded')}</td><td>${esc(value(b)||'Not recorded')}</td></tr>`).join('')}</tbody></table></div>`:'<p>At least two drivers in this scope are needed to compare. Add a driver or choose another module scope.</p>'}`;
 return `<div class="${ui.section==='compare'?'f-quality-comparison':'q-work-body'}">${body}</div>`;
}
function pairInScope(pair){return !shellLens()||pair.driverIds.some(inScope)}
function outsideScopeNote(pair){return shellLens()&&pair.driverIds.some(id=>!inScope(id))?'<p class="r-note">Includes drivers outside this module scope.</p>':''}
function conflictList(){return project.quality.conflicts.filter(pairInScope).map(c=>`<div class="q-conflict"><div><small>${esc(c.id)} · ${esc(c.driverIds.join(' / '))}</small>${outsideScopeNote(c)}<h3>${esc(c.title)}</h3><p>${esc(c.effect)}</p><span class="chip ${conflictIsResolved(project,c)?'pass':'reference'}">${conflictIsResolved(project,c)?'Resolved':c.status==='resolved'?'Needs re-review':'Open conflict'}</span>${c.resolution?`<p><b>Resolution:</b> ${esc(c.resolution)}</p>`:''}</div><button class="r-btn" data-q-conflict="${esc(c.id)}">Review</button></div>`).join('')||'<p class="r-note">No conflicts recorded for the drivers in this scope.</p>'}
function tradeoffList(d,scoped=false){const pairs=potentialTradeoffs(project,d).filter(t=>!scoped||pairInScope(t));return pairs.map(t=>`<article class="q-tradeoff"><small>${esc(t.driverIds.join(' / '))} · ${t.shared.map(id=>esc(projectResponsibilities(project).find(r=>r.id===id)?.title)).join(', ')}</small>${scoped?outsideScopeNote(t):''}<h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p>${t.existingId?`<button class="r-btn" data-q-conflict="${esc(t.existingId)}">Review recorded trade-off</button>`:`<button class="r-btn gold" data-q-tradeoff="${esc(t.id)}">Record for review</button>`}</article>`).join('')||'<p class="r-note">No potential trade-offs match the current responsibility links. This does not prove that none exist.</p>'}
// Round 12 (GR-DOM-05): the tactics released knowledge offers for the driver's category (domain-knowledge.js), each with
// its release and reviewer; none while nothing is released. A person names the tactic in the scenario if it applies.
function releasedTacticList(d){const ts=releasedTactics(project,d.category);return ts.length?`<h3>Released tactics for ${esc(concern(d).name)}</h3><ul class="q-released-tactics">${ts.map(t=>`<li><b>${esc(t.name)}</b> ${esc(t.statement)} <small>Released knowledge · ${esc(t.receipt.releaseId)} · verified by ${esc(t.receipt.review?.reviewer||'a second person')}</small></li>`).join('')}</ul>`:'';}
// rc39: what this driver asks of the design (design-questions.js driverQuestions): its playbook attribute and family, the
// questions it opens with the chapter each is decided in and the records it lands on by state, and the tactics the
// playbook names for the attribute. The chapter link opens that chapter's Work on the first record the question lands on.
const shapeWords=id=>TARGET_SHAPES.find(s=>s.id===id)?.words||'';
function designAsksHTML(d){
 const q=driverQuestions(project,d.id);if(!q)return '';
 const a=q.driver.attribute,landing=x=>{const n={open:0,draft:0,decided:0};for(const l of x.lands)n[l.state]++;return x.lands.length?`lands on ${x.lands.length} ${x.lands.length===1?'record':'records'} · ${['open','draft','decided'].filter(k=>n[k]).map(k=>n[k]+' '+k).join(' · ')}`:'lands on no record yet';};
 const where=x=>{const first=x.lands[0];return first?`<a href="${esc(projectURL('/?chapter='+x.chapter+'&tab=work&object='+encodeURIComponent(first.id)))}">decided in Chapter ${x.chapter} ${icon('arrow')}</a>`:`decided in Chapter ${x.chapter}`;};
 return `<section class="q-design-asks" data-design-asks="${esc(d.id)}"><h3>What this driver asks of the design</h3><p>${a?`<b>${esc(a.name)}</b> · ${a.family?esc(a.family.name)+' family':'no playbook family'}`:`<b>${esc(kindLabel(d))} driver</b>`}${q.driver.shape?` · ${esc(shapeWords(q.driver.shape))}`:''}</p><ul class="q-design-questions">${q.questions.map(x=>`<li data-design-question="${esc(x.id)}"><b>${esc(x.title)}</b><small>${where(x)} · ${landing(x)}</small></li>`).join('')||'<li>No design question opens from this driver yet.</li>'}</ul>${a?.tactics.length?`<h3>Tactics the playbook names for ${esc(a.name)}</h3><ul class="q-design-tactics">${a.tactics.map(t=>`<li>${esc(t.name)}<small> · ${esc(t.group)}</small></li>`).join('')}</ul>`:''}</section>`;
}
const designAsksLine=d=>{const q=driverQuestions(project,d.id);return q?` · opens ${q.questions.length} design ${q.questions.length===1?'question':'questions'} · ${q.counts.decided} decided`:'';};
// The details of the record in view, then the one lifecycle path (round 12, GR-GOV-23): retire it, restore what left.
function inspector(){const key=ui.node,d=selected();return inspectorBody()+(key&&!key.startsWith('driver:')?'':lifecycleHTML(project,2,d?.id,'data-q-action'));}
function inspectorBody(){
 const key=ui.node,d=selected();if(key&&!key.startsWith('driver:'))return contextInspector(key);
 const g=qualityGuidance(project,d,ui.tab),ps=qualityProposals(project,d,ui.tab),measured=d&&isMeasured(d);
 return `<header class="r-inspector-head"><span>${icon('cursor')}Details</span></header><div class="r-inspector-body">${button('back-surface','Back to workspace','r-mobile-return')}${d?`<p class="r-kicker">${esc(driverCode(project,d))} · ${esc(kindLabel(d))}${measured?' · '+esc(concern(d).name):''}</p><h2>${esc(d.title)}</h2>${badge(d)}<p>${esc(measured?d.response||'Describe the expected response.':d.description||'Describe what this driver asks of the design.')}</p>${measured?`<div class="q-measure-card"><small>${esc(d.metric||'Metric missing')}</small><strong>${esc(targetText(d))}</strong>${targetBadge(d)}<p>${esc(d.window||'Measurement window missing')}</p></div>`:`<div class="q-measure-card"><small>Architectural impact</small><strong>${esc(d.impact||'Impact not recorded')}</strong></div>`}<div class="r-actions"><button class="r-btn primary" data-q-edit="${esc(d.id)}">${icon('edit')}Edit ${measured?'quality scenario':'driver'}</button>${button('compare-selected','Compare')}</div><dl><div><dt>Priority and reason</dt><dd>${esc(driverPriority(d)||'Not stated')} · ${esc(d.rationale||'Not recorded')}</dd></div>${measured?`<div><dt>Stimulus</dt><dd>${esc(d.stimulus||'Not recorded')}</dd></div><div><dt>Operating conditions</dt><dd>${esc(d.conditions||'Not recorded')}</dd></div><div><dt>How to verify</dt><dd>${esc(d.measurement||'Not recorded')}</dd></div>`:`<div><dt>Description</dt><dd>${esc(d.description||'Not recorded')}</dd></div>`}<div><dt>Owner</dt><dd>${esc(d.owner||'Not recorded')}</dd></div><div><dt>Evidence / source</dt><dd>${esc(d.source||'Not recorded')}</dd></div><div><dt>Origin</dt><dd>${esc(recordProvenance(project,d,2).label)}</dd></div></dl>${sourceChanged(project,d)?'<div class="r-error">A source record changed. Revisit this driver against its current sources.</div>':''}<h3>Source requirements</h3><div class="q-link-list">${d.requirementIds.map(id=>{const a=project.artefacts.find(a=>a.id===id);return a?`<button data-q-context="requirement:${esc(id)}"><b>${esc(a.externalId||id)}</b> ${esc(a.title)}<small>${a.confirmed?'Confirmed':'Unconfirmed source'}</small></button>`:`<span class="r-error">${esc(id)} is missing</span>`}).join('')||'<p>No requirements linked.</p>'}</div><h3>Affected responsibilities</h3><div class="q-link-list">${d.responsibilityIds.map(id=>`<a href="${esc(projectURL('/?chapter=4&object='+encodeURIComponent(id)))}">${esc(projectResponsibilities(project).find(r=>r.id===id)?.title||id)} ${icon('arrow')}</a>`).join('')||'<p>No responsibilities linked.</p>'}</div>${designAsksHTML(d)}${measured?`<h3>Candidate tactic</h3><p>${esc(d.tactic||'Explore a tactic in Co-design.')}</p>${releasedTacticList(d)}`:''}`:`<h2>Define an architectural driver.</h2><p>Start from current requirements or outcomes. For a quality scenario, record its stimulus, conditions, expected response, and measurement.</p>`}${evidenceContextHTML(project,d?.id,ui.tab)}<div class="r-attention"><p class="r-kicker">A useful next thought</p><p>${esc(g.attention)}</p><small>${esc(g.next)}</small>${ps[0]?`<button class="r-btn gold" data-q-proposal="${esc(ps[0].id)}">${icon('spark')}Explore a draft suggestion</button>`:''}</div>${d?`<h3>Potential trade-offs</h3>${tradeoffList(d)}`:''}</div>`;
}
function contextRecord(key){const [kind,id]=key.split(':');return kind==='driver'?driver(id):kind==='responsibility'?projectResponsibilities(project).find(n=>n.id===id):project.artefacts.find(a=>a.id===id)}
function contextDrivers(key){const [kind,id]=key.split(':');return orderedDrivers(project).filter(d=>kind==='requirement'?d.requirementIds.includes(id):kind==='responsibility'?d.responsibilityIds.includes(id):driverOutcomes(project,d).some(o=>o.id===id))}
function contextInspector(key){const a=contextRecord(key);if(!a){ui.node=null;return inspector()}const [kind,id]=key.split(':'),ds=contextDrivers(key);return `<header class="r-inspector-head"><span>${icon('cursor')}Details</span></header><div class="r-inspector-body">${button('back-surface','Back to workspace','r-mobile-return')}<p class="r-kicker">${esc(kind)} · ${esc(id)}</p><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p>${a.acceptance?`<h3>Acceptance</h3><p>${esc(a.acceptance)}</p>`:''}${a.source?`<h3>Source / evidence</h3><p>${esc(a.source)}</p>`:''}<h3>Connected architectural drivers</h3><div class="q-link-list">${ds.map(d=>`<button data-q-select="${esc(d.id)}"><b>${esc(driverCode(project,d))} · ${esc(d.title)}</b><small>${esc(driverSummary(d))} · ${esc(driverPriority(d)||'Priority not stated')}</small></button>`).join('')||'<p>No connected drivers yet.</p>'}</div><div class="r-actions"><a class="r-btn" href="${esc(projectURL(kind==='responsibility'?'/?chapter=4&object='+encodeURIComponent(id):'/?chapter=1&tab=work&artefact='+encodeURIComponent(id)))}">Open source ${icon('arrow')}</a></div><div class="r-attention"><p>These ${ds.length} drivers depend on this ${esc(kind)}. Review their impacts and quality targets together when its behaviour changes.</p></div></div>`}
function validation(){return validationSurfaceHTML(project,2,{title:'Review driver definitions and evidence',purpose:'Check architectural impact and priority; quality scenarios also need measurable responses and targets.',run:button('validate','Run checks','primary'),findings:qualityFindings(project).map(f=>({...f,objectId:f.driverId,reference:driver(f.driverId)?driverCode(project,driver(f.driverId)):f.driverId,actions:'<button type="button" class="btn" data-q-fix="'+esc(f.id)+'">Open remedy</button>'}))});}
function output(){const ds=orderedDrivers(project),quality=ds.filter(isMeasured);return outputWorkspaceHTML(project,2,{title:'The prioritised architectural driver brief',summary:ds.length+' architectural drivers · '+quality.length+' quality scenarios · '+quality.filter(d=>d.targetConfirmed).length+' confirmed targets',context:'<p>Named priority and explicit ordering determine this register. Measured targets apply to quality scenarios; other kinds state their architectural impact. Candidate tactics remain proposals for Chapter 3.</p>',handoff:'<h3>Carry the drivers into architectural decisions</h3><p>Stable driver and scenario references, source requirements, candidate tactics, and open findings travel together.</p><p>'+esc(qualityHandoffCurrent(project)?'Current handoff recorded':'Working revision · handoff needs review')+'</p>'+button('handoff',qualityHandoffCurrent(project)?'Open Chapter 3 decisions':'Review & carry forward','gold')});}
