function select(id){if(!driver(id))return;const again=document.activeElement?.dataset?.qSelect===id;ui.selected=id;ui.node=null;hideTip();if(ui.tab==='work'&&ui.section==='intake')ui.section='scenarios';render();window.dispatchEvent(new CustomEvent('aiw:inspect-details'));if(again)refocus('data-q-select',id)}
