function dialog(title,body,kind){if(presentAssistant(kind,title,body))return;const open=$('.q-dialog'),opener=open?open.opener:rememberOpener(document.activeElement);if(open)closeSharedDialog(open,{restoreFocus:false});ui.modal=kind;ui.dirty=false;hideTip();const el=openDialog({className:'dialog l-dialog r-dialog q-dialog',labelledBy:'q-dialog-title',opener,html:`<header><div><span class="eyebrow">Chapter 02 / ${esc(ui.tab)}</span><h2 id="q-dialog-title">${title}</h2></div>${dbtn('close',icon('close'),'icon-only','aria-label="Close dialog"')}</header><div id="q-form-error" class="l-error" role="alert" hidden></div>${body}<div id="q-discard" class="l-discard" hidden><p>Discard your unsaved changes?</p>${dbtn('keep-editing','Keep editing')}${dbtn('discard','Discard changes')}</div>`,onCancel:()=>closeDialog(),closeSelector:null});refineAssistantDialog(el,kind);}
function closeDialog(force=false,{restore=true}={}){if(ui.busy&&!force)return null;if(ui.dirty&&!force){$('#q-discard').hidden=false;$('#q-discard button').focus();return null}const el=$('.q-dialog'),opener=el?.opener||null;ui.modal=null;ui.dirty=false;if(el)closeSharedDialog(el,{restoreFocus:restore});return opener}
function blankDriver(requirementId){return {kind:ui.kind==='all'?'quality':ui.kind,category:'integrity',priority:'',description:'',impact:'',priorityBasis:'',requirementGroupIds:[],outcomeIds:[],constraintIds:[],componentIds:[],operator:'At most',targetValue:'',requirementIds:requirementId?[requirementId]:[],responsibilityIds:requirementId&&project.artefacts.find(a=>a.id===requirementId)?.modelRef?[project.artefacts.find(a=>a.id===requirementId).modelRef]:[],title:'',stimulus:'',conditions:'',response:'',metric:'',unit:'',window:'',measurement:'',owner:'',source:'',rationale:'',tactic:'',confirmed:false,targetConfirmed:false,origin:'user'}}
function editDriver(id=null,proposal=null,requirementId=null,step=0,preset=null){sync();const old=id?driver(id):null,d={...(proposal?.record||old||blankDriver(requirementId)),...(preset||{})};if(old&&sourceChanged(project,old))d.confirmed=false;formRecord={id:old?.id,origin:proposal?'suggestion':old?.origin||'user'};const kind=driverKind(d);if(kind!=='quality'&&step===1)step=2;ui.step=step;const only=ks=>`data-q-kinds="${ks}" ${ks.split(' ').includes(kind)?'':'hidden'}`,artefacts=t=>project.artefacts.filter(a=>a.type===t).map(a=>({id:a.id,strong:a.id,title:a.title}));dialog(proposal?'Review & edit the driver proposal':old?'Edit '+driverCode(project,old):'Add a driver',`<form id="q-driver-form"><nav class="l-steps" aria-label="Driver editing steps">${[[0,'Driver'],[1,'Measurement'],[2,'Traceability & priority']].map(([i,label])=>`<button type="button" class="btn${i===step?' active':''}" data-q-form-step="${i}" aria-pressed="${i===step}" ${i===1&&kind!=='quality'?'hidden':''}>${label}</button>`).join('')}</nav><section data-q-panel="0" ${step!==0?'hidden':''}><div class="l-form-grid">${fDriver('kind',kind,{options:DRIVER_KINDS.map(k=>[k.id,k.name])})}<div ${only('quality')}>${fDriver('category',d.category,{options:QUALITY_TYPES.map(t=>[t.id,t.name])})}</div>${fDriver('title',d.title)}</div>${fDriver('description',d.description||'')}${fDriver('impact',d.impact||'')}<div ${only('quality')}>${fDriver('stimulus',d.stimulus)}${fDriver('conditions',d.conditions)}${fDriver('response',d.response)}</div>${dbtn('form-next',(kind==='quality'?'Next: measurement ':'Next: traceability & priority ')+icon('arrow'))}</section><section data-q-panel="1" ${step!==1?'hidden':''}><p class="r-note" ${only('business functional constraint operational data technology-evolution business-continuity')}>Only a quality driver has a measured target. Continue to its links and priority.</p><div ${only('quality')}><div class="r-reference-note">Numerical examples are editable assumptions. Confirm the metric and threshold against agreed evidence.</div>${fDriver('metric',d.metric)}<div class="q-target-fields">${fDriver('operator',d.operator,{options:OPERATORS.map(o=>[o,o])})}${fDriver('targetValue',d.targetValue)}${fDriver('unit',d.unit)}</div>${fDriver('window',d.window)}${fDriver('measurement',d.measurement)}${fDriver('targetConfirmed',d.targetConfirmed)}</div>${dbtn('form-next','Next: traceability & priority '+icon('arrow'))}</section><section data-q-panel="2" ${step!==2?'hidden':''}>${fDriver('requirementIds',d.requirementIds,{options:reqs().map(a=>({id:a.id,strong:a.id,title:a.title,note:a.confirmed?'Confirmed':'Unconfirmed source'})),empty:'Add requirements in Chapter 1 first.'})}${fDriver('requirementGroupIds',d.requirementGroupIds||[],{options:requirementGroups(project).map(g=>({id:g.id,strong:g.id,title:g.title,note:kindName(g.kind)})),empty:'No requirement group yet.'})}<div ${only('business')}>${fDriver('outcomeIds',d.outcomeIds||[],{options:artefacts('outcome'),empty:'Add business outcomes in Chapter 1 first.'})}</div><div ${only('constraint')}>${fDriver('constraintIds',d.constraintIds||[],{options:artefacts('constraint'),empty:'Add constraints in Chapter 1 first.'})}</div>${fDriver('responsibilityIds',d.responsibilityIds,{options:projectResponsibilities(project).map(r=>({id:r.id,title:r.title}))})}${fDriver('componentIds',d.componentIds||[],{options:(project.realisation?.components||[]).map(c=>({id:c.id,strong:c.ref,title:c.title})),empty:'No application component yet.'})}<div class="l-form-grid">${fDriver('priority',driverPriority(d),{options:[['','Not stated'],...QUALITY_PRIORITIES.map(x=>[x,x])]})}${fDriver('priorityBasis',d.priorityBasis||'',{options:[['','Not recorded'],...PRIORITY_BASIS.map(x=>[x,x.charAt(0).toUpperCase()+x.slice(1)])]})}${fDriver('owner',d.owner)}</div>${fDriver('rationale',d.rationale)}${fDriver('source',d.source)}<div ${only('quality')}>${fDriver('tactic',d.tactic)}</div>${fDriver('confirmed',d.confirmed)}<p class="r-note">${old?driverCode(project,old)+' and '+old.id+' remain unchanged.':'A stable code of its kind is given on save.'} Confirmation records your review; it does not approve a design.</p></section><div class="l-dialog-actions">${old?dbtn('lifecycle-retire','Retire driver','danger',`data-lifecycle-id="${esc(old.id)}"`):''}${dbtn('close','Cancel')}<button type="submit" class="btn primary">${proposal?'Apply edited proposal':'Save driver'}</button></div></form>`,'driver');$('#q-driver-form [name=kind]').value=kind;formStep(step)}
function formStep(step,{check=false}={}){if(check&&!canLeaveStep($('#q-driver-form'),'data-q-panel',step))return;if($('#q-driver-form [name=kind]')?.value!=='quality'&&step===1)step=2;ui.step=Math.max(0,Math.min(2,step));document.querySelectorAll('[data-q-panel]').forEach(el=>el.hidden=Number(el.dataset.qPanel)!==ui.step);document.querySelectorAll('[data-q-form-step]').forEach(el=>{const on=Number(el.dataset.qFormStep)===ui.step;el.setAttribute('aria-pressed',String(on));el.classList.toggle('active',on)});$('.r-dialog').scrollTop=0;$('[data-q-panel="'+ui.step+'"] input,[data-q-panel="'+ui.step+'"] textarea,[data-q-panel="'+ui.step+'"] select')?.focus()}
