function contextMenu(kind){const a=contextRecord(ui.node),ds=contextDrivers(ui.node),[type,id]=ui.node.split(':');if(!a)return;const prompt={work:'Which connected driver needs a clearer impact or target?',model:'Which drivers share this source or responsibility, and where might they compete?',validate:'Which source changes or unresolved findings affect these drivers?',output:'Which driver references should inform the next architectural decision?'}[ui.tab];dialog(kind==='sol'?'Sol · Act on this context':'Co-design · Explore this context',`<p>Chapter 2 / ${esc(ui.tab)} · ${esc(type+' '+id)}</p><h3>${esc(a.title)}</h3><div class="r-reference-note">${prompt}</div>${kind==='sol'?`<div class="r-actions"><a class="r-btn" href="${esc(projectURL(type==='responsibility'?'/?chapter=4&object='+encodeURIComponent(id):'/?chapter=1&tab=work&artefact='+encodeURIComponent(id)))}">Open source ${icon('arrow')}</a>${type==='requirement'?`<button type="button" class="r-btn" data-q-from-requirement="${esc(id)}">Add a linked driver</button>`:''}</div>`:'<p>Compare the connected impacts and measured quality targets. Choose a driver to inspect its reasoning.</p>'}${ds.map(d=>`<article class="r-pattern"><h3>${esc(d.id)} · ${esc(d.title)}</h3><p>${esc(driverSummary(d))}</p>${kind==='mind'&&isMeasured(d)?`<p>${esc(d.tactic||'No candidate tactic is recorded yet.')}</p>`:''}<button type="button" class="r-btn" data-q-select="${esc(d.id)}">Explore ${esc(d.id)}</button></article>`).join('')}`,kind);}
